package releaseverify

import (
	"context"
	"errors"
	"io/fs"
	"path/filepath"
	"testing"

	tursodb "github.com/gopernicus/gopernicus/integrations/datastores/turso"
	_ "github.com/gopernicus/gopernicus/integrations/datastores/turso/localfile"
	"github.com/gopernicus/gopernicus/pockets/authentication/logic/invitations"
	"github.com/gopernicus/gopernicus/pockets/authorization"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/model"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/mutations"
	"github.com/gopernicus/gopernicus/pockets/authorization/logic/relationships"
	"github.com/gopernicus/gopernicus/pockets/authorization/stores/memory"
	pgstore "github.com/gopernicus/gopernicus/pockets/authorization/stores/pgx"
	sqlstore "github.com/gopernicus/gopernicus/pockets/authorization/stores/turso"
	"github.com/gopernicus/gopernicus/sdk"
)

func exercise(t *testing.T, repos authorization.Repositories) mutations.Command {
	t.Helper()
	ctx := context.Background()
	c, err := authorization.New(repos)
	if err != nil {
		t.Fatal(err)
	}
	cmd := mutations.Command{
		OperationID:   "invitation:public-smoke",
		Target:        mutations.Target{Kind: mutations.TargetResource, Type: "project", ID: "one"},
		Operation:     mutations.OpGrant,
		Relationships: []mutations.RelationshipRow{{Relation: "member", Subject: relationships.SubjectRef{Type: "user", ID: "alice"}}},
	}
	first, err := c.Mutations.Apply(ctx, cmd)
	if err != nil || first.Replayed || first.Outcome != mutations.OutcomeApplied {
		t.Fatalf("first=%+v err=%v", first, err)
	}
	revoke := cmd
	revoke.OperationID = ""
	revoke.Operation = mutations.OpRevoke
	if _, err := c.Mutations.Apply(ctx, revoke); err != nil {
		t.Fatal(err)
	}
	replay, err := c.Mutations.Apply(ctx, cmd)
	if err != nil || !replay.Replayed || !replay.Superseded || replay.Outcome != first.Outcome {
		t.Fatalf("replay=%+v err=%v", replay, err)
	}
	present, err := c.Roles.HasRoleIn(ctx, model.PrincipalRef{Type: "user", ID: "alice"}, "member", model.Resource{Type: "project", ID: "one"})
	if err != nil || present {
		t.Fatalf("access restored=%v err=%v", present, err)
	}
	mismatch := cmd
	mismatch.Relationships = []mutations.RelationshipRow{{Relation: "owner", Subject: relationships.SubjectRef{Type: "user", ID: "alice"}}}
	if _, err := c.Mutations.Apply(ctx, mismatch); !errors.Is(err, mutations.ErrOperationMismatch) || !errors.Is(err, sdk.ErrConflict) {
		t.Fatalf("mismatch=%v", err)
	}
	if !errors.Is(invitations.ErrGrantSuperseded, sdk.ErrConflict) {
		t.Fatal("superseded lost conflict mapping")
	}
	return cmd
}

func TestPublicMemoryLedger(t *testing.T) {
	s := memory.New()
	exercise(t, authorization.Repositories{Tuples: s.Tuples(), Mutations: s.Mutations()})
}

func TestPublicSQLiteLedgerRestart(t *testing.T) {
	ctx := context.Background()
	cfg := tursodb.Config{URL: "file:" + filepath.Join(t.TempDir(), "iam.db")}
	db, err := tursodb.Open(ctx, cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := sqlstore.Repositories(ctx, db); err == nil {
		t.Fatal("unmigrated constructor succeeded")
	}
	for _, mig := range []struct {
		schema fs.FS
		dir    string
	}{{sqlstore.MigrationsFS, sqlstore.MigrationsDir}, {pgstore.MigrationsFS, pgstore.MigrationsDir}} {
		if _, err := fs.ReadFile(mig.schema, mig.dir+"/0003_iam_operations.sql"); err != nil {
			t.Fatal(err)
		}
	}
	if err := tursodb.RunMigrations(ctx, db, sqlstore.MigrationsFS, sqlstore.MigrationsDir); err != nil {
		t.Fatal(err)
	}
	repos, err := sqlstore.Repositories(ctx, db)
	if err != nil {
		t.Fatal(err)
	}
	cmd := exercise(t, repos)
	freshDB, err := tursodb.Open(ctx, cfg)
	if err != nil {
		t.Fatal(err)
	}
	defer freshDB.Close()
	fresh, err := sqlstore.Repositories(ctx, freshDB)
	if err != nil {
		t.Fatal(err)
	}
	result, err := fresh.Mutations.Apply(ctx, cmd, func(mutations.Command) error { return sdk.ErrForbidden })
	if err != nil || !result.Replayed || !result.Superseded {
		t.Fatalf("restart=%+v err=%v", result, err)
	}
	var count int
	if err := freshDB.QueryRow(ctx, "SELECT count(*) FROM iam_operations").Scan(&count); err != nil || count != 1 {
		t.Fatalf("ledger rows=%d err=%v", count, err)
	}
}
